<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_login();$user=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'create';
 if($action==='delete'){$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$stmt=$pdo->prepare('SELECT template_image FROM twibbons WHERE id=? AND owner_id=?');$stmt->execute([$id,$user['id']]);if($item=$stmt->fetch()){$pdo->prepare('DELETE FROM twibbons WHERE id=? AND owner_id=?')->execute([$id,$user['id']]);$path=__DIR__.'/uploads/'.basename($item['template_image']);if(is_file($path))@unlink($path);flash('success','Template berhasil dihapus.');}}
 else{try{$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));if($title===''||mb_strlen($title)>120)throw new RuntimeException('Judul wajib diisi dan maksimal 120 karakter.');$name=store_image($_FILES['template_image']??[],__DIR__.'/uploads');$slug=random_slug();$stmt=$pdo->prepare("INSERT INTO twibbons(slug,owner_id,visibility,title,description,template_image) VALUES(?,?,'unlisted',?,?,?)");$stmt->execute([$slug,$user['id'],$title,$description,$name]);flash('success','Template berhasil dibuat. Salin tautannya dan mulai bagikan.');}catch(Throwable $e){flash('error',$e->getMessage());}}
 header('Location: dashboard.php');exit;}
$flash=pull_flash();$stmt=$pdo->prepare('SELECT * FROM twibbons WHERE owner_id=? ORDER BY created_at DESC');$stmt->execute([$user['id']]);$items=$stmt->fetchAll();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard — Twibbo</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="home.php"><span class="brand-mark">T</span>Twibbo</a><nav class="nav-links"><a href="home.php">Beranda</a><?php if(is_admin()):?><a href="admin.php">Admin</a><?php endif?><a class="active" href="dashboard.php"><?=e($user['name'])?></a><a href="logout.php">Keluar</a></nav></div></header><main class="container"><div class="page-head dashboard-head"><div><span class="eyebrow">Dashboard kreator</span><h1 class="page-title" style="margin-top:12px">Halo, <?=e(explode(' ',$user['name'])[0])?>.</h1><p class="subtitle">Buat template privat via tautan dan bagikan ke audiensmu.</p></div><button class="btn btn-primary" onclick="document.querySelector('#newTemplate').scrollIntoView()">＋ Template baru</button></div><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif?><div class="dashboard-grid" style="margin-bottom:24px"><div class="card stat"><strong><?=count($items)?></strong><span>Total template</span></div><div class="card stat"><strong><?=count($items)?></strong><span>Tautan aktif</span></div><div class="card stat"><strong>Privat</strong><span>Hanya dapat diakses via URL</span></div></div><div class="admin-layout"><section class="panel" id="newTemplate"><h2>Buat template</h2><p class="panel-note">Template tidak tampil di katalog publik. Siapa pun dengan tautannya dapat menggunakannya.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="field"><label for="title">Nama kampanye</label><input id="title" name="title" maxlength="120" required placeholder="Contoh: Anniversary komunitas"></div><div class="field"><label for="description">Deskripsi</label><textarea id="description" name="description" rows="3" maxlength="500"></textarea></div><div class="field"><label for="template_image">Bingkai PNG transparan</label><input id="template_image" name="template_image" type="file" accept="image/png,image/jpeg,image/webp" required></div><button class="btn btn-primary">Buat dan dapatkan tautan</button></form></section><section class="panel"><h2>Template saya</h2><p class="panel-note">Salin tautan untuk membagikannya.</p><?php if(!$items):?><div class="empty">Belum ada template. Buat template pertamamu.</div><?php endif?><?php foreach($items as $item):$url='create.php?s='.rawurlencode($item['slug']);?><div class="admin-item"><img src="uploads/<?=e(basename($item['template_image']))?>" alt=""><div><h3><?=e($item['title'])?> <span class="visibility visibility-unlisted">Via tautan</span></h3><div class="copy-group"><input value="<?=e($url)?>" readonly><button type="button" class="btn btn-secondary btn-sm" onclick="copyLink('<?=e($url)?>',this)">Salin</button><a class="btn btn-secondary btn-sm" href="<?=e($url)?>">Buka</a></div></div><form method="post" onsubmit="return confirm('Hapus template ini?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="btn btn-danger btn-sm">Hapus</button></form></div><?php endforeach?></section></div></main><footer class="footer">Twibbo · Produk digital dari Apins Digital</footer><script>async function copyLink(url,button){const full=new URL(url,location.href).href;await navigator.clipboard.writeText(full);const old=button.textContent;button.textContent='Tersalin';setTimeout(()=>button.textContent=old,1500)}</script></body></html>
